---初始化杂货铺列表数据
function GroceryAsyncPVPNode:InitGroceryData()
    local data = GroceryMgr:GetRegionalData()
    local productData = {}
    for _, v in ipairs(data.products) do
        if productData[checkInt(v.tab)] then
            table.insert(productData[checkInt(v.tab)], v)
        else
            productData[checkInt(v.tab)] = {v}
        end
    end
    local groceryData = {}
    for i, v in ipairs(productData) do
        groceryData[i] = {
            products = v,
            text     = TabTitle[i]
        }
    end
    return groceryData
end

