---重置按钮点击回调
function GroceryAsyncPVPNode:BtnResetOnClickHandler()
    local progress = self:GetBuyProgress()
    local progressMax = self:GetProgressMaxNum()
    if progress < progressMax then
        GameUtils.Toast(localize("领取全部奖励后可重置进度"))
        return 
    end

    local rewards = self:GetProgressRewards()
    for _, v in ipairs(rewards) do
        if checkInt(v.status) ~= Constants.GetStatus.Has then
            GameUtils.Toast(localize("还有进度奖励未领取噢"))
            return
        end
    end

    GameUtils.Request(Interfaces.GroceryAsyncReset, {}, Bind(self, self.ProgressRewardsResetResponseHandler))
    
end

---奖励节点点击回调
function GroceryAsyncPVPNode:RewardsNodeOnClickHandler(sender)
    -- 是否可领取
    if sender:GetNodeDrawState() == Constants.GetStatus.Can then
        GameUtils.Request(Interfaces.GroceryAsyncPVPDraw, {}, Bind(self, self.ProgressRewardsDrawResponseHandler))
    elseif sender:GetNodeDrawState() == Constants.GetStatus.Has then
        GameUtils.Toast(localize('奖励已领取'))
    else
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(sender:GetRewardGoodsId())
        GameUtils.ShowCommonTipsBoard(sender.controller, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
    end
end

---进度奖励领取回调处理
function GroceryAsyncPVPNode:ProgressRewardsDrawResponseHandler(request, response)
    local responseData = checkTable(response.data)
    GoodsUtils.DrawRewards(responseData.rewards)
    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })

    local progressRewards = self:GetProgressRewards()
    for _, v in ipairs(progressRewards) do
        if checkInt(v.status) == 1 then
            v.status = 2
        end
    end
    self:RefreshProgressRewards()
end

---进度奖励重置回调处理
function GroceryAsyncPVPNode:ProgressRewardsResetResponseHandler(request, response)
    Events.Broadcast(Constants.EventNames.GROCERY_HOME_REFRESH)
end
