--region private
---刷新进度奖励
function GroceryAsyncPVPNode:RefreshProgressRewards()
    local rewardsVo = CfUtils.GetCf(AutoIds.IdSetting3089, "StoreAsyncPVPRewardsVo", true)
    local progressRewards = self:GetProgressRewards()
    local progress = self:GetBuyProgress()
    local maxNum = self:GetProgressMaxNum()
    CfUtils.SetSliderPercent(self.Slider,progress / maxNum)
    CfUtils.FillText(self.TextNumber, math.min(progress, maxNum))
    
    -- 进度条
    for i = 1, #progressRewards do
        local node = self.Reward:Find("OverseaStoreRewardNode" .. i)
        if not isNull(node) then
            local scr = CfUtils.GetLuaScr(node, GroceryConstants.ScrPath.GroceryProgressRewardNode)
            if not isNull(scr) then
                local reward = {
                    goodsId = rewardsVo[i].reward,
                    num     = rewardsVo[i].rewardNum,
                }
                local params = {
                    reward = reward,
                    times  = rewardsVo[checkInt(progressRewards[i].id)].amount,
                    level  = i,
                }
                scr:RefreshData(i, params)
                scr:SetNodeDrawState(progressRewards[i].status)
                scr:SetClickNodeCB(Bind(self, self.RewardsNodeOnClickHandler))
            end
            
            local pos = Vector2(0, 0)
            pos.x = self.Slider.sizeDelta.x * (checkNumber(rewardsVo[checkNumber(progressRewards[i].id)].amount) / maxNum)
            local pos2 = self.Slider:TransformPoint(pos)
            local pos3 = self.Reward:InverseTransformPoint(pos2)
            node.localPosition = Vector2(pos3.x, node.localPosition.y)
        end
    end
end

---刷新页签状态
function GroceryAsyncPVPNode:RefreshTabState()
    -- 更新页签锁定状态
    local rewards = self:GetProgressRewards()
    local progress = self:GetBuyProgress()
    local env = CfUtils.GetLuaScr(self.CommonTabToggleUp.gameObject, GroceryConstants.ScrPath.CommonTabToggleUp)
    for i = 1, #self:GetGroceryData() do
        if i == 1 then
            env:SetLockState(i, false)
        else
            local rewardsVo = CfUtils.GetCfVo(AutoIds.IdSetting3089, "StoreAsyncPVPRewardsVo", rewards[i - 1].id)
            if rewardsVo then
                print(i, progress, rewardsVo.amount)
                if progress >= checkInt(rewardsVo.amount) then
                    env:SetLockState(i, false)
                else
                    env:SetLockState(i, true)
                end
            end
        end
    end
end

---刷新锁定状态
function GroceryAsyncPVPNode:RefreshLockState()
    local selectedTab = self:GetSelectedTab()
    if selectedTab == 1 then
        CfUtils.SetActive(self.Lock, false)
        return
    end
    
    local rewards = self:GetProgressRewards()
    local progress = self:GetBuyProgress()
    local rewardsVo = CfUtils.GetCfVo(AutoIds.IdSetting3089, "StoreAsyncPVPRewardsVo", rewards[selectedTab - 1].id)
    if not rewardsVo then return end

    if progress >= checkInt(rewardsVo.amount) then
        CfUtils.SetActive(self.Lock, false)
    else
        CfUtils.SetActive(self.Lock, true)
        CfUtils.FillText(self.LockTextDesc, localize("购买进度达到_num_", {_num_ = rewardsVo.amount}))
    end
end

---播放进入动画
function GroceryAsyncPVPNode:PlayEnterAnimation()
    self.Root:Stop()
